  KEY `SHIPPER_ID` (`SHIPPER_ID`),
  CONSTRAINT `1` FOREIGN KEY (`SHIPPER_ID`) REFERENCES `SHIPPER` (`SHIPPER_ID`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
